`timescale 1ns/1ps
module tb_eth_mac_mmio;
 reg cc=0,mc=0,cr=0,mr=0,wr=0;always#7 cc=~cc;always#4 mc=~mc;reg[31:0]addr=0,wd=0;reg[3:0]ws=4'hf;wire[31:0]rd;wire hit;reg[7:0]rxd=0;reg rxv=0,rxe=0;wire[7:0]txd;wire txv;wire[7:0]tx_delay_step,rx_delay_step;
 eth_mac_mmio dut(.sys_clk(cc),.sys_resetn(cr),.addr(addr),.wr(wr),.wdata(wd),.wstrb(ws),.rdata(rd),.hit(hit),.mac_clk(mc),.mac_resetn(mr),.mac_rx_data(rxd),.mac_rx_valid(rxv),.mac_rx_byte_valid(rxv),.mac_rx_error(rxe),.mac_tx_data(txd),.mac_tx_valid(txv),.mac_tx_ready(1'b1),.tx_delay_step(tx_delay_step),.rx_delay_step(rx_delay_step));
 task mw(input[31:0]a,input[31:0]d);begin @(negedge cc);addr=a;wd=d;wr=1;@(negedge cc);wr=0;end endtask
 integer count=0,i;reg[7:0]cap[0:127];reg[31:0]crc,fcs;always@(posedge mc)if(txv)begin cap[count]=txd;count=count+1;end
 task cb;input[31:0]c;input[7:0]d;output[31:0]next_crc;integer k;reg[31:0]v;begin v=c;for(k=0;k<8;k=k+1)if(v[0]^d[k])v=(v>>1)^32'hedb88320;else v=v>>1;next_crc=v;end endtask
 initial begin repeat(4)@(posedge cc);cr=1;mr=1;if(tx_delay_step!=100||rx_delay_step!=247)$fatal(1,"bad delay defaults");mw(32'h1fe0101c,32'h00008040);if(tx_delay_step!=64||rx_delay_step!=128)$fatal(1,"delay register write failed");for(i=0;i<60;i=i+4)mw(32'h1fe03000+i,i|((i+1)<<8)|((i+2)<<16)|((i+3)<<24));mw(32'h1fe0100c,60);mw(32'h1fe01010,2);repeat(200)@(posedge mc);if(count!=72)$fatal(1,"TX byte count %0d",count);for(i=0;i<7;i=i+1)if(cap[i]!=8'h55)$fatal(1,"bad preamble");if(cap[7]!=8'hd5||cap[8]!=0||cap[67]!=59)$fatal(1,"bad payload");
  crc=32'hffff_ffff;for(i=0;i<60;i=i+1)cb(crc,i,crc);fcs=~crc;if(cap[68]!==fcs[7:0]||cap[69]!==fcs[15:8]||cap[70]!==fcs[23:16]||cap[71]!==fcs[31:24])$fatal(1,"bad TX FCS %02x%02x%02x%02x expected %08x",cap[71],cap[70],cap[69],cap[68],fcs);@(negedge mc);rxv=1;for(i=0;i<8;i=i+1)begin rxd=(i==7)?8'hd5:8'h55;@(negedge mc);end for(i=0;i<60;i=i+1)begin rxd=i;@(negedge mc);end for(i=0;i<4;i=i+1)begin rxd=fcs[i*8+:8];@(negedge mc);end rxv=0;repeat(8)@(posedge cc);addr=32'h1fe01004;#1;if(!rd[0])$fatal(1,"RX not ready");addr=32'h1fe01008;#1;if(rd[10:0]!=64)$fatal(1,"RX len %0d",rd[10:0]);addr=32'h1fe02000;#1;if(rd!==32'h03020100)$fatal(1,"RX data %h",rd);$display("PASS tb_eth_mac_mmio");$finish;end
endmodule
